def count_distinct_photos(n, m, board):
    def get_neighbors(x, y):
        neighbors = []
        if x > 0:
            neighbors.append((x - 1, y))
        if x < n - 1:
            neighbors.append((x + 1, y))
        if y > 0:
            neighbors.append((x, y - 1))
        if y < m - 1:
            neighbors.append((x, y + 1))
        return neighbors

    def dfs(x, y, visited):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) not in visited:
                visited.add((cx, cy))
                for nx, ny in get_neighbors(cx, cy):
                    if board[nx][ny] == board[cx][cy]:
                        stack.append((nx, ny))

    visited = set()
    components = 0
    for i in range(n):
        for j in range(m):
            if (i, j) not in visited:
                dfs(i, j, visited)
                components += 1

    return components * (components - 1) // 2

